import { auditRuntimeCapabilities } from '../diagnostics/capability-truth-audit.js';
import { readPersistentCapabilityStress, startPersistentCapabilityStress } from '../diagnostics/persistent-capability-stress.js';

export function registerCapabilityAuditCapability(bus, env = {}) {
  bus.discover({
    id: 'capability.audit',
    name: 'Audit vérité des capacités MEL',
    category: 'diagnostic',
    version: '1.0.0',
    provider: 'core',
    description: 'Inventories every registered runtime capability and optionally executes only bounded LOW-risk smoke samples.',
    input_schema: {
      type: 'object',
      properties: {
        deep: { type: 'boolean' },
        strict: { type: 'boolean' },
      },
      additionalProperties: false,
    },
    output_schema: { type: 'object', additionalProperties: true },
    risk: 'LOW',
    permissions: [],
    health: 'HEALTHY',
    enabled: true,
  }, async (input, context = {}) => {
    const auditContext = {
      owner: context.owner || 'capability-audit',
      permissions: context.permissions || [],
      approvedCapabilities: context.approvedCapabilities || [],
      requestId: context.requestId || crypto.randomUUID(),
      waitUntil: context.waitUntil,
    };
    // In read‑only mode (or when a custom stub is provided) we must not start a
    // persistent stress test that would mutate state or incur paid calls.
    if (input.deep === true && env?.DB && !env?.READ_ONLY) {
      const starter = env._startPersistentCapabilityStress || startPersistentCapabilityStress;
      return starter({ bus, db: env.DB, context: auditContext, strict: input.strict === true });
    }
    const auditor = env._auditRuntimeCapabilities || auditRuntimeCapabilities;
    return auditor(
      { bus },
      {
        deep: input.deep === true,
        strict: input.strict === true,
        context: auditContext,
      }
    );
  });

  bus.discover({
    id: 'capability.audit.status',
    name: 'Statut du stress test global des capacités MEL',
    category: 'diagnostic',
    version: '1.0.0',
    provider: 'core',
    description: 'Reads the latest durable global capability stress-test job or one exact job_id without executing another audit.',
    input_schema: {
      type: 'object',
      properties: {
        job_id: { type: 'string', minLength: 1, maxLength: 200 },
      },
      additionalProperties: false,
    },
    output_schema: { type: 'object', additionalProperties: true },
    risk: 'LOW',
    permissions: [],
    health: env?.DB ? 'HEALTHY' : 'UNAVAILABLE',
    enabled: true,
  }, async (input) => {
    if (!env?.DB) throw Object.assign(new Error('CAPABILITY_STRESS_DB_REQUIRED'), { code: 'CAPABILITY_STRESS_DB_REQUIRED' });
    return readPersistentCapabilityStress({ db: env.DB, jobId: input.job_id || null });
  });
}

export function registerSelfAuditCapabilities(bus, env = {}) {
  bus.discover({
    id: 'self.audit.status',
    name: 'Statut du Self-Audit Supervisor',
    category: 'diagnostic',
    version: '1.0.0',
    provider: 'core',
    description: 'Reads the persistent MEL self-audit cadence, latest report, latest global stress job and repair state without starting a new audit.',
    input_schema: { type: 'object', additionalProperties: false },
    output_schema: { type: 'object', additionalProperties: true },
    risk: 'LOW',
    permissions: [],
    health: env?.DB ? 'HEALTHY' : 'UNAVAILABLE',
    enabled: true,
  }, async () => {
    const { readMelSelfAuditStatus } = await import('../diagnostics/self-audit-supervisor.js');
    return readMelSelfAuditStatus(env);
  });

  bus.discover({
    id: 'self.audit.run',
    name: 'Lancer le Self-Audit Supervisor',
    category: 'diagnostic',
    version: '1.0.0',
    provider: 'core',
    description: 'Runs a bounded MEL self-audit level. HEARTBEAT is lightweight, DAILY refreshes health and watch pipelines, WEEKLY starts the durable full capability stress, MONTHLY adds non-destructive survival and backup drills.',
    input_schema: {
      type: 'object',
      properties: {
        level: { type: 'string', enum: ['HEARTBEAT','DAILY','WEEKLY','MONTHLY'] },
      },
      additionalProperties: false,
    },
    output_schema: { type: 'object', additionalProperties: true },
    risk: 'MEDIUM',
    permissions: [],
    health: env?.DB ? 'HEALTHY' : 'UNAVAILABLE',
    enabled: true,
  }, async (input, context = {}) => {
    const { runMelSelfAuditSupervisor } = await import('../diagnostics/self-audit-supervisor.js');
    const level = String(input?.level || 'DAILY').toUpperCase();
    if (context?.releaseSmoke === true && level !== 'HEARTBEAT') {
      const error = new Error('SELF_AUDIT_RELEASE_SMOKE_HEARTBEAT_ONLY');
      error.code = 'SELF_AUDIT_RELEASE_SMOKE_HEARTBEAT_ONLY';
      error.status = 403;
      throw error;
    }
    return runMelSelfAuditSupervisor(env, {
      bus,
      forceLevel: level,
      maxLevel: level,
      repairEnabled: context?.releaseSmoke !== true,
      waitUntil: typeof context?.waitUntil === 'function' ? context.waitUntil : null,
    });
  });
  // Deep audit capability: runs capability.audit with deep=true and returns counts of called, refused, and failed capabilities
  bus.discover({
    id: 'self.audit.deep',
    name: 'Lancer le Self-Audit Profond',
    category: 'diagnostic',
    version: '1.0.0',
    provider: 'core',
    description: 'Executes capability.audit with deep=true and returns counts of called, refused, and failed capabilities.',
    input_schema: { type: 'object', additionalProperties: false },
    output_schema: {
      type: 'object',
      properties: {
        called: { type: 'integer' },
        refused: { type: 'integer' },
        failed: { type: 'integer' },
        verified: { type: 'integer' },
      },
      required: ['called', 'refused', 'failed', 'verified'],
      additionalProperties: false,
    },
    risk: 'LOW',
    permissions: [],
    health: env?.DB ? 'HEALTHY' : 'UNAVAILABLE',
    enabled: true,
  }, async (input, context = {}) => {
    const auditResult = await bus.execute('capability.audit', { deep: true });
    const rows = Array.isArray(auditResult?.rows) ? auditResult.rows : [];
    const called = rows.filter(r => r.execution).length;
    const refused = rows.filter(r => r.truth_status === 'REFUSEE').length;
    const failed = rows.filter(r => r.execution && r.execution.ok === false).length;
    const verified = rows.filter(r => r.truth_status === 'VERIF_DECLARATIVE').length;
    return { called, refused, failed, verified };
  });
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { registerSelfAuditCapabilities } from '../src/capabilities/self-audit-capability.js';

test('self.audit.deep returns correct counts', async () => {
  const handlers = {};
  const bus = {
    discover: (def, handler) => { handlers[def.id] = handler; },
    execute: async (id, payload) => {
      if (id === 'capability.audit') {
        return {
          rows: [
            { execution: { ok: true }, truth_status: 'OK' },
            { execution: { ok: false }, truth_status: 'OK' },
            { truth_status: 'REFUSEE' },
            { truth_status: 'VERIF_DECLARATIVE' },
            { /* no execution and not refused */ },
          ],
        };
      }
      throw new Error('Unexpected execute id');
    },
  };
  registerSelfAuditCapabilities(bus, {});
  const result = await handlers['self.audit.deep']({}, {});
  assert.deepEqual(result, { called: 2, refused: 1, failed: 1, verified: 1 });
});

test('capability.audit respects read‑only mode and does not start persistent stress', async () => {
  let startCalled = false;
  const mockStart = () => {
    startCalled = true;
    return { rows: [] };
  };
  const mockAudit = () => ({ rows: [{ execution: { ok: true }, truth_status: 'OK' }] });
  const bus = {
    discover: (def, handler) => { /* no need to store handlers for this test */ },
    execute: async (id, payload) => {
      if (id === 'capability.audit') {
        // This path should be reached only if the handler falls back to the
        // runtime auditor (read‑only mode).
        return mockAudit();
      }
      throw new Error('Unexpected execute id');
    },
  };
  // Register the capability with a DB (to trigger the persistent path) but
  // enforce read‑only mode and provide a stub for the starter.
  const env = { DB: {}, READ_ONLY: true, _startPersistentCapabilityStress: mockStart };
  const { registerCapabilityAuditCapability } = await import('../src/capabilities/capability-audit-capability.js');
  registerCapabilityAuditCapability(bus, env);
  // Directly invoke the discovered handler for `capability.audit`.
  const auditHandler = (await import('../src/capabilities/capability-audit-capability.js')).registerCapabilityAuditCapability;
  // Since the discover registration stores the handler internally, we simulate
  // the call by executing through the bus.
  const result = await bus.execute('capability.audit', { deep: true });
  assert.equal(startCalled, false, 'Persistent stress starter must not be called in read‑only mode');
  assert.deepEqual(result, { rows: [{ execution: { ok: true }, truth_status: 'OK' }] });
});
